-- Hand-written: integrity backstops Prisma cannot express. The tenant pattern repeats the
-- kernel's single rule (parseTenantId); the others repeat the module's domain rules.
ALTER TABLE "tenancy"."site"
  ADD CONSTRAINT "site_tenant_id_check" CHECK ("tenant_id" ~ '^[a-z][a-z0-9-]{1,31}$'),
  ADD CONSTRAINT "site_slug_check" CHECK ("slug" ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  ADD CONSTRAINT "site_name_check" CHECK (char_length(btrim("name")) > 0),
  ADD CONSTRAINT "site_depth_check" CHECK ("depth" >= 0 AND ("depth" = 0) = ("parent_site_id" IS NULL)),
  ADD CONSTRAINT "site_not_own_parent_check" CHECK ("parent_site_id" IS DISTINCT FROM "id"),
  ADD CONSTRAINT "site_version_check" CHECK ("version" >= 1);

ALTER TABLE "tenancy"."site_ancestry"
  ADD CONSTRAINT "site_ancestry_depth_check" CHECK ("depth" >= 0 AND ("depth" = 0) = ("ancestor_id" = "descendant_id"));

ALTER TABLE "tenancy"."site_domain"
  ADD CONSTRAINT "site_domain_hostname_check" CHECK ("hostname" ~ '^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$'),
  ADD CONSTRAINT "site_domain_path_prefix_check" CHECK ("path_prefix" ~ '^(/[a-z0-9]+(-[a-z0-9]+)*)*$');

ALTER TABLE "tenancy"."organization"
  ADD CONSTRAINT "organization_tenant_id_check" CHECK ("tenant_id" ~ '^[a-z][a-z0-9-]{1,31}$'),
  ADD CONSTRAINT "organization_name_check" CHECK (char_length(btrim("name")) > 0),
  ADD CONSTRAINT "organization_depth_check" CHECK ("depth" >= 0 AND ("depth" = 0) = ("parent_id" IS NULL)),
  ADD CONSTRAINT "organization_not_own_parent_check" CHECK ("parent_id" IS DISTINCT FROM "id"),
  ADD CONSTRAINT "organization_version_check" CHECK ("version" >= 1);

ALTER TABLE "tenancy"."organization_ancestry"
  ADD CONSTRAINT "organization_ancestry_depth_check" CHECK ("depth" >= 0 AND ("depth" = 0) = ("ancestor_id" = "descendant_id"));

ALTER TABLE "tenancy"."tenant_settings"
  ADD CONSTRAINT "tenant_settings_tenant_id_check" CHECK ("tenant_id" ~ '^[a-z][a-z0-9-]{1,31}$'),
  ADD CONSTRAINT "tenant_settings_sign_in_sources_check" CHECK (
    "sign_in_sources" IS NOT NULL
    AND cardinality("sign_in_sources") BETWEEN 1 AND 2
    AND "sign_in_sources" <@ ARRAY['directory', 'local']::VARCHAR(16)[]
  ),
  ADD CONSTRAINT "tenant_settings_max_site_depth_check" CHECK ("max_site_depth" BETWEEN 1 AND 32),
  ADD CONSTRAINT "tenant_settings_version_check" CHECK ("version" >= 1 AND "structure_version" >= 0);

-- Grants. The group role "phoenix_app" is created by the cluster bootstrap, never by a
-- migration. No DELETE on sites or organizations: retiring one is a later slice.
GRANT USAGE ON SCHEMA "tenancy" TO "phoenix_app";
GRANT SELECT, INSERT, UPDATE ("parent_site_id", "organization_id", "slug", "name", "depth", "version", "updated_at") ON TABLE "tenancy"."site" TO "phoenix_app";
GRANT SELECT, INSERT, DELETE ON TABLE "tenancy"."site_ancestry" TO "phoenix_app";
GRANT SELECT, INSERT, DELETE ON TABLE "tenancy"."site_domain" TO "phoenix_app";
GRANT SELECT, INSERT, UPDATE ("parent_id", "name", "depth", "version", "updated_at") ON TABLE "tenancy"."organization" TO "phoenix_app";
GRANT SELECT, INSERT, DELETE ON TABLE "tenancy"."organization_ancestry" TO "phoenix_app";
GRANT SELECT, INSERT, UPDATE ("sign_in_sources", "max_site_depth", "structure_version", "version", "updated_at") ON TABLE "tenancy"."tenant_settings" TO "phoenix_app";

-- Row-level security (ADR-02), the reference policy of platform.isolation_probe on every table.
ALTER TABLE "tenancy"."site" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "site_tenant_isolation" ON "tenancy"."site"
  AS PERMISSIVE FOR ALL TO "phoenix_app"
  USING ("tenant_id" = "platform"."current_tenant_id"())
  WITH CHECK ("tenant_id" = "platform"."current_tenant_id"());

ALTER TABLE "tenancy"."site_ancestry" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "site_ancestry_tenant_isolation" ON "tenancy"."site_ancestry"
  AS PERMISSIVE FOR ALL TO "phoenix_app"
  USING ("tenant_id" = "platform"."current_tenant_id"())
  WITH CHECK ("tenant_id" = "platform"."current_tenant_id"());

ALTER TABLE "tenancy"."site_domain" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "site_domain_tenant_isolation" ON "tenancy"."site_domain"
  AS PERMISSIVE FOR ALL TO "phoenix_app"
  USING ("tenant_id" = "platform"."current_tenant_id"())
  WITH CHECK ("tenant_id" = "platform"."current_tenant_id"());

ALTER TABLE "tenancy"."organization" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "organization_tenant_isolation" ON "tenancy"."organization"
  AS PERMISSIVE FOR ALL TO "phoenix_app"
  USING ("tenant_id" = "platform"."current_tenant_id"())
  WITH CHECK ("tenant_id" = "platform"."current_tenant_id"());

ALTER TABLE "tenancy"."organization_ancestry" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "organization_ancestry_tenant_isolation" ON "tenancy"."organization_ancestry"
  AS PERMISSIVE FOR ALL TO "phoenix_app"
  USING ("tenant_id" = "platform"."current_tenant_id"())
  WITH CHECK ("tenant_id" = "platform"."current_tenant_id"());

ALTER TABLE "tenancy"."tenant_settings" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "tenant_settings_tenant_isolation" ON "tenancy"."tenant_settings"
  AS PERMISSIVE FOR ALL TO "phoenix_app"
  USING ("tenant_id" = "platform"."current_tenant_id"())
  WITH CHECK ("tenant_id" = "platform"."current_tenant_id"());
